{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "@id": "https://kubaik.github.io/opentelemetry-collector-pipelines-sampling-batching/#faq",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Why does my OpenTelemetry collector drop spans under load?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The most common cause is backpressure from a slow exporter or an expensive processor. When the pipeline cannot keep up, the receiver's queue fills and it starts refusing data. Check otelcolreceiverrefusedspans and otelcolexportersendfailedspans to confirm. Adding a memorylimiter processor at the start of the pipeline and reducing batch size can help."
      }
    },
    {
      "@type": "Question",
      "name": "Should I use probabilistic or tail-based sampling in the collector?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Probabilistic sampling is cheap and stateless, but it drops errors and slow traces at the same rate as everything else. Tail-based sampling keeps traces based on policies, but it requires buffering spans and a two-tier collector setup to ensure all spans for a trace reach the same instance. Use probabilistic sampling for high-volume, low-value data and tail sampling for the traces you need for debugging."
      }
    },
    {
      "@type": "Question",
      "name": "How do I route different telemetry to different backends?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Use the routing connector or the filter processor to split data based on attributes. Define separate pipelines for each destination and attach the routing connector as an exporter in the source pipeline and as a receiver in the destination pipelines. Be aware that each destination pipeline has its own resource cost, and a slow backend can back up the shared source pipeline unless you isolate it."
      }
    },
    {
      "@type": "Question",
      "name": "What is a safe batch size for the OpenTelemetry collector?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "There is no universal safe size. Calculate the memory cost: batch size times average item size times number of in-flight batches. For spans averaging 1 KB, a batch size of 2,000 uses about 2 MB per batch. Keep the total batching memory under 10% of the collector's memory limit. Also set sendbatchmaxsize to prevent oversized batches."
      }
    }
  ]
}
